{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 BPM Switcher\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Switch BPM to 120/240/360\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Usage\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Just run the script from Actions\par}
}

