{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Create regions from text items\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Convert text items to project regions\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Creates regions from all items on selected track\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Item Notes are transferred to region names\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Region timing matches items\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Useful for converting track content to timeline marking\sa180\par}
}

