{\pard \ql \f0 \sa180 \li0 \fi0 Convert project regions to text items\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Creates new track with text items based on all project regions\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Region names are transferred to item Notes\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Item timing matches regions\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Convenient for transferring marking to tracks\sa180\par}
}

