{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Export items to SRT\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Export text items from selected track to SRT subtitle file\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Exports all items from selected track\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Creates standard SRT file with timecodes\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Text is taken from Notes of each item\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Suitable for transferring subtitles to other programs\sa180\par}
}

