{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Export regions to SRT\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Export project regions to SRT subtitle file\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Exports all project regions\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Creates standard SRT file with timecodes\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Region names become subtitle text\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Quick way to create subtitles from project marking\sa180\par}
}

