{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Import regions from subtitles\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Import SRT/ASS subtitles as project regions in REAPER\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Supports SRT and ASS formats\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Auto-detects encoding (UTF-8, CP1251, CP866)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab For ASS files with roles - assigns unique color to each role (20 bright colors)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Regions are created with subtitle text as names and precise timecode\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Convenient for quick project marking by subtitles\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Import text items from subtitles\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Import SRT/ASS subtitles as text items in REAPER\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Supports SRT and ASS formats (multiple file selection)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Auto-detects encoding (UTF-8, CP1251, CP866)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab For ASS files with roles - creates separate track for each role\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Tracks are named by filename (or "filename - role" for ASS with roles)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Items are created with precise timecode and text in Notes\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
